import{_ as s,C as n,o as d,c as e,j as i,E as r,a as l,a2 as o}from"./chunks/framework.C21TwvGF.js";const z=JSON.parse(`{"title":"2-hafta (Mentor)","description":"","frontmatter":{"title":"2-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"n":2,"bob":"I-bob · Game Design asoslari","lessons":[{"g":4,"title":"O‘yin loyihalash va ssenariy: G'oyadan voqealar zanjirigacha","lead":"Kitobda siz hikoyani o'qiysiz, kinoda uni ko'rasiz, o'yinda esa siz ushbu hikoyaning ichida yashaysiz va uni o'zingiz yaratasiz!","link":"/mentor/9-sinf-game/hafta-02/dars-1","slide":"/slaydlar/9-sinf-game/hafta-02/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-02/dars-1-test.html"},{"g":5,"title":"Photoshop interfeysi va vositalari (1-qism): 2D grafika turlari va interfeys","lead":"2D o'yin san'ati — bu har bir piksel va chiziq orqali virtual dunyoni jonlantirish, o'yinchiga estetik zavq va unutilmas vizual muhit ulashish mahoratidir!","link":"/mentor/9-sinf-game/hafta-02/dars-2","slide":"/slaydlar/9-sinf-game/hafta-02/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-02/dars-2-test.html"},{"g":6,"title":"Photoshop interfeysi va vositalari (2-qism): Tanlash vositalari, qatlamlar va uskunalar","lead":"Professional grafik dizayner hech qachon rasmni buzib o'chirmaydi. U niqoblar (maskalar) va qatlamlar orqali sehrli o'zgarishlar yaratadi!","link":"/mentor/9-sinf-game/hafta-02/dars-3","slide":"/slaydlar/9-sinf-game/hafta-02/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-02/dars-3-test.html"}],"test":"/slaydlar/9-sinf-game/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-02/index.md","filePath":"mentor/9-sinf-game/hafta-02/index.md"}`),h={name:"mentor/9-sinf-game/hafta-02/index.md"},g={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},y={class:"blk"},u={id:"baholash-mezoni",tabindex:"-1"};function v(q,a,f,b,k,c){const t=n("Icon");return d(),e("div",null,[i("div",g,[i("h2",m,[r(t,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_4-dars-o-yin-loyihalash-va-ssenariy-high-concept-hikoya-turlari-va-gdd" tabindex="-1">4-dars: O‘yin loyihalash va ssenariy: High Concept, hikoya turlari va GDD <a class="header-anchor" href="#_4-dars-o-yin-loyihalash-va-ssenariy-high-concept-hikoya-turlari-va-gdd" aria-label="Permalink to &quot;4-dars: O‘yin loyihalash va ssenariy: High Concept, hikoya turlari va GDD&quot;">​</a></h2><ol><li>O&#39;zingiz orzu qilgan 2D o&#39;yin uchun 2–3 ta jumlada lo&#39;nda va jozibador <strong>High Concept</strong> yozing.</li><li>Qahramoningiz sayohatini Jozef Kempbellning &quot;Qahramon sayohati&quot; (Hero&#39;s Journey) modelining kamida 4 ta bosqichi (Oddiy olam, Chaqiriq, Sinovlar, G&#39;alaba) orqali yoritib bering.</li><li>O&#39;yiningiz ssenariysi qaysi turga mansubligini (Chiziqli, Tarmoqlanuvchi yoki Ochiq olam) belgilang va o&#39;yinchining bitta qarori voqealar rivojiga qanday ta&#39;sir qilishini tasvirlang.</li><li>O&#39;yin sahnasiga dialoglarsiz voqeani tushuntiruvchi bitta atrof-muhit detali (<strong>Environmental Storytelling</strong>) o&#39;ylab toping (masalan, kimsasiz xonada yoniq qolgan kompyuter yoki singan qalqon).</li></ol><hr><h2 id="_5-dars-photoshop-interfeysi-va-vositalari-1-qism-2d-grafika-spraytlar-va-canvas" tabindex="-1">5-dars: Photoshop interfeysi va vositalari (1-qism): 2D grafika, spraytlar va Canvas <a class="header-anchor" href="#_5-dars-photoshop-interfeysi-va-vositalari-1-qism-2d-grafika-spraytlar-va-canvas" aria-label="Permalink to &quot;5-dars: Photoshop interfeysi va vositalari (1-qism): 2D grafika, spraytlar va Canvas&quot;">​</a></h2><ol><li>O&#39;yin grafikasida nima uchun 32x32 yoki 64x64 pikselli <strong>Tayllar (Tiles)</strong> va <strong>Spraytlar (Sprites)</strong> ishlatilishini, ularning o&#39;yin xotirasi (RAM)ga ta&#39;sirini tushuntiring.</li><li>3 ta chuqurlik qatlamidan iborat <strong>Parallaks foni (Parallax Scrolling)</strong> ssenariysini tuzing (osmon, uzoq tog&#39;lar, oldingi o&#39;rmon) va qaysi biri qanday tezlikda harakatlanishini yozing.</li><li>Photoshopda 2D mobil platformer o&#39;yini uchun yangi hujjat ochish parametrlarini aniqlang: Canvas o&#39;lchami (Width/Height px), Resolution (DPI), Color Mode va Background Contents.</li><li>Rastrli grafikaning 2 ta kamchiligini va Vektorli grafikaning 2 ta ustunligini o&#39;yin dizayni nuqtai nazaridan sanab o&#39;ting.</li></ol><hr><h2 id="_6-dars-photoshop-interfeysi-va-vositalari-2-qism-tanlash-vositalari-layer-masks-va-blending-modes" tabindex="-1">6-dars: Photoshop interfeysi va vositalari (2-qism): Tanlash vositalari, Layer Masks va Blending Modes <a class="header-anchor" href="#_6-dars-photoshop-interfeysi-va-vositalari-2-qism-tanlash-vositalari-layer-masks-va-blending-modes" aria-label="Permalink to &quot;6-dars: Photoshop interfeysi va vositalari (2-qism): Tanlash vositalari, Layer Masks va Blending Modes&quot;">​</a></h2><ol><li>Bir xil rangdagi oq fonda joylashgan o&#39;yin assetini ajratib olib, yangi shaffof qatlamga o&#39;tkazishning 3 ta qadamini ketma-ket yozing (asboblar va klaviatura tugmalari bilan).</li><li>Professional o&#39;yin artistlari nima uchun o&#39;chirg&#39;ich (Eraser Tool) o&#39;rniga <strong>Layer Mask (Qatlam niqobi)</strong> ishlatishini, uning oq va qora ranglari qanday ishlashini tushuntiring.</li><li>Qora fonga ega bo&#39;lgan alanga (olov) rasmidagi qora fonni yo&#39;qotib, faqat porlovchi olovni qahramonning qo&#39;liga tutqazish uchun qaysi <strong>Blending Mode</strong> qo&#39;llanilishini va bu rejim qanday ishlashini yozing.</li><li>Mo&#39;yqalam (Brush Tool) bilan ishlaganda o&#39;tkir qirrali sprayt chizish va tumanli sehrli nur taratish uchun <strong>Hardness</strong> parametri qanday qiymatlarga qo&#39;yilishini ayting.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>4-dars vazifasi (30 ball):</strong> High Concept lo&#39;ndaligi, qahramon sayohati bosqichlari to&#39;g&#39;ri qo&#39;llangani va environmental storytelling g&#39;oyasi mavjudligi.</li><li><strong>5-dars vazifasi (35 ball):</strong> 2D grafika komponentlari (sprayt, tayl, parallaks) va Canvas sozlamalari (piksel, DPI, RGB) to&#39;g&#39;ri tahlil qilingani.</li><li><strong>6-dars vazifasi (35 ball):</strong> Tanlash vositalari (Wand, Lasso), destruktiv bo&#39;lmagan tahrir (Layer Mask) va Blending Modes (Screen, Multiply) ishlash mexanizmini amaliy tushunilgani.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchilar uy vazifasini nazariy javoblar bilan birga, Photoshopda ochilgan fayllar yoki eksport qilingan skrinshotlar orqali topshirishlari rag&#39;batlantiriladi.</li></ul>',16))]),i("div",y,[i("h2",u,[r(t,{name:"list-checks"}),a[3]||(a[3]=l(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p><strong>Mavzular:</strong></p><ol><li>O‘yin loyihalash va ssenariy: High Concept, ssenariy turlari (chiziqli, tarmoqlanuvchi), Hero&#39;s Journey, Environmental Storytelling va GDD</li><li>Photoshop interfeysi va vositalari (1-qism): 2D grafikaning o&#39;rni, spraytlar, tayllar, parallaks, rastr vs vektor vs fraktal, Canvas sozlamalari</li><li>Photoshop interfeysi va vositalari (2-qism): Tanlash vositalari (Marquee, Lasso, Wand), Brush, Pen, Shape, Gradient, Layer Masks va Blending Modes</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>O&#39;yin Loyihalash va Ssenariy</strong></td><td>High Concept tuzish, Hero&#39;s Journey bosqichlari, tarmoqlanuvchi syujet, Environmental Storytelling, GDD arxitekturasi</td><td>30 ball</td></tr><tr><td><strong>2D Grafika va Canvas Asoslari</strong></td><td>Sprayt va tayllar roli, Parallaks effekti qatlamlari, Rastr vs Vektor xususiyatlari, Canvas sozlamalari (px, DPI, RGB)</td><td>35 ball</td></tr><tr><td><strong>Photoshop Vositalari va Qatlamlar</strong></td><td>Tanlash vositalari (Wand, Lasso, Marquee), Brush va Pen xususiyatlari, Layer Masks (oq/qora) va Blending Modes (Multiply, Screen)</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Loyihalash &amp; Ssenariy (30)</th><th>2D Grafika &amp; Canvas (35)</th><th>Vositalar &amp; Maskalar (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar dastlabki amaliyotda piksellarni yo&#39;qotib yubormaslik uchun o&#39;chirg&#39;ich (Eraser) o&#39;rniga qatlam niqobi (Layer Mask)dan foydalanish psixologiyasiga o&#39;rganishlari biroz vaqt talab qiladi. Maskanıng &quot;Qora berkitadi, oq ko&#39;rsatadi&quot; qoidasini turli misollar bilan mustahkamlash lozim. Shuningdek, Pen Tool bilan ishlaganda Bezye egri chiziqlarini boshqarishda qo&#39;l ko&#39;nikmasini shakllantirish uchun ko&#39;proq mashq zarur.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> Photoshopda o&#39;z qahramoni uchun to&#39;liq sprayt-shit (Sprite Sheet) qolipini tayyorlash yoki ko&#39;p qatlamli parallaks fon kollajini yaratish vazifasi topshirilishi mumkin.</li></ul>',11))])])}const P=s(h,[["render",v]]);export{z as __pageData,P as default};
